  "pdf.overview": "Synthèse de session", "pdf.covSummary": "Résumé", "pdf.covMapCap": "Tous les points et régions évalués", "pdf.covCounts": "{p} points évalués · {r} régions", "pdf.covList": "Lieux évalués", "pdf.conversation": "Conversation", "pdf.pointDetails": "Détails du point",
