  "pdf.overview": "Resumen de sesión", "pdf.covSummary": "Resumen", "pdf.covMapCap": "Todos los puntos y regiones evaluados", "pdf.covCounts": "{p} puntos evaluados · {r} regiones", "pdf.covList": "Ubicaciones evaluadas", "pdf.conversation": "Conversación", "pdf.pointDetails": "Detalles del punto",
