  "pdf.subtitle": "Assistente de prospectividade - Austrália Ocidental",
  "pdf.overview": "Resumo da sessão", "pdf.covSummary": "Resumo", "pdf.covMapCap": "Todos os pontos e regiões avaliados", "pdf.covCounts": "{p} pontos avaliados · {r} regiões", "pdf.covList": "Locais avaliados", "pdf.conversation": "Conversa", "pdf.pointDetails": "Detalhes do ponto",
  "pdf.nearestSite": "DEPÓSITO CONHECIDO MAIS PRÓXIMO", "pdf.openOnMap": "Abrir no mapa",
