  "pdf.latlon": "lat {lat}, lon {lon}",
  "pdf.team": "Equipe", "pdf.teamTitle": "A equipe por trás da plataforma",
  "pdf.teamIntro": "O MineTrace e a pesquisa em torno dele vêm do Tema 4 - Acelerando a inteligência de geodados do ARC Training Centre in Critical Resources for the Future (CCRF), com o apoio do UWA Centre for Natural and Technical Language Processing (NTLP). Liderado pelo Professor Associado Wei Liu, o Tema 4 adota uma abordagem coordenada de ciência de geodados em todo o Centro para descoberta, caracterização e processamento de minerais críticos baseados em evidências.",
  "pdf.teamMore": "Mais sobre a equipe",
  "pdf.tr.wei": "Líder do tema", "pdf.tb.wei": "Lidera o NTLP - Centre for Natural and Technical Language Processing - e o Tema 4 do centro de treinamento, definindo a direção que conecta grafos de conhecimento, IA generativa e LLMs multimodais à exploração mineral.",
  "pdf.tr.pascal": "Base da plataforma", "pdf.tb.pascal": "Assentou a base da plataforma em que o MineTrace roda - construída para sustentar os modelos e a pesquisa que ainda virão.",
  "pdf.tr.yihao": "Pesquisa central - MineTrace", "pdf.tb.yihao": "Pesquisa central no MineTrace: compreensão multimodal de documentos, recuperação de informação e perguntas e respostas sobre o acervo de exploração.",
  "pdf.tr.yiran": "Pesquisa central - MineTrace", "pdf.tb.yiran": "Pesquisa central no MineTrace: grafos de conhecimento ao longo da cadeia de valor dos minerais críticos, transformando o acervo em conhecimento consultável.",
  "pdf.tr.jinwen": "Prova de conceito inicial", "pdf.tb.jinwen": "Desenvolveu a prova de conceito inicial que estabeleceu a abordagem, e que depois se tornou esta plataforma.",
  "pdf.tr.daniel": "Nas duas frentes", "pdf.tb.daniel": "Atua nas frentes de pesquisa e de plataforma com modelos fundacionais multimodais, e estende a abordagem a outros casos de uso de exploração.",
  "pdf.tr.chris": "Visualização de dados e consultor de geologia", "pdf.tb.chris": "Orienta a visualização de dados e traz o olhar de um geólogo à plataforma - ancorando a apresentação e a leitura dos resultados na prática geológica.",
  "about.eyebrow": "Sobre", "about.whoTitle": "Quem construiu",
  "about.mtLabel": "A pesquisa",
  "about.mtBody": "O MineTrace é o modelo de prospectividade mineral por trás de cada pontuação desta plataforma. Ele lê o acervo público de exploração - geoquímica GSWA, geofísica e estruturas mapeadas - e o converte em uma pontuação que permanece rastreável até a evidência de onde veio.",
  "about.seriesLabel": "O que vem a seguir",
  "about.seriesTitle": "Uma plataforma feita para sustentar mais de um modelo",
  "about.seriesBody": "A plataforma não pontua por conta própria: ela chama um serviço de pesquisa por HTTP e plota o que retorna. O MineTrace é o primeiro modelo nesses trilhos - construídos para sustentar a pesquisa que vier, de modo que cada novo resultado chegue a quem de fato explora, em vez de parar num artigo.",
  "about.ccrfEyebrow": "Parte de um ARC Training Centre",
  "about.ccrfTheme": "Tema 4 - Acelerando a inteligência de geodados",
  "about.af.wei": "NTLP, UWA - Líder do Tema 4, CCRF",
  "about.af.jinwen": "Estudante de graduação, Ciência da Computação e Engenharia de Software, UWA",
  "about.af.yihao": "Pesquisador de pós-doutorado, CCRF",
  "about.af.yiran": "Doutorando, CCRF",
  "about.af.pascal": "NTLP, UWA",
  "about.af.daniel": "Doutorando, UWA - em colaboração com o CCRF",
  "about.af.chris": "Pesquisador (Research Fellow), CCRF & CET, UWA",
  // ── research hub ──
  "research.eyebrow": "Pesquisa", "research.title": "Pesquisa",
  "research.intro": "A nossa investigação liga dados, evidências e raciocínio: prospetividade mineral, inteligência documental e acesso a bases de dados em linguagem natural. GeoPlatform oferece um ambiente geocientífico para explorar estes métodos.",
  "research.ladder": "O que cresce a partir daí",
  "research.st.retrieval.t": "Recuperação", "research.st.retrieval.b": "Encontrar o registo, a página ou o valor. Por exemplo: text-to-SQL sobre os dados estruturados, leitura aumentada por recuperação sobre os documentos.",
  "research.st.reasoning.t": "Raciocínio", "research.st.reasoning.b": "Combinar a evidência num juízo que permaneça rastreável. Por exemplo: a prospectividade mineral com o MineTrace.",
  "research.st.reflection.t": "Reflexão", "research.st.reflection.b": "Deixar o sistema rever o que leu e pontuou e fazer emergir conhecimento que ninguém inseriu à mão. Por exemplo: uma hipótese de exploração extraída de padrões em milhares de relatórios.",
  "research.group.application": "Aplicação", "research.group.foundation": "Fundamentos",
  "research.open": "Saiba mais", "research.back": "Toda a pesquisa",
  "research.minetrace.blurb": "Um sistema web de prospetividade mineral com um índice compósito de prospetividade (CPI) rastreável, evidências e explicações assistidas por um LLM.",
  "research.di.blurb": "Explorar coleções de documentos em escala - o arquivo de exploração, a literatura científica e as publicações do Serviço Geológico - como conhecimento estruturado e pesquisável, com cada fato ligado à sua página.",
  "research.text2sql.blurb": "Tornar mensurável a consulta em linguagem natural numa base de dados privada - o Acuity transforma qualquer esquema num benchmark sem anotação e usa-o para melhorar e implantar a pesquisa.",
  "pdf.teamAck": "Agradecimento",
  "pdf.teamAckBody": "A pesquisa subjacente, MineTrace, conta com o apoio do ARC Training Centre in Critical Resources for the Future, no âmbito do Tema 4 - Acelerando a inteligência de geodados.",
  "pdf.teamGroup": "NTLP, UWA",
  "pdf.teamGroupBody": "O Centre for Natural and Technical Language Processing (NTLP) da UWA pesquisa reconhecimento de entidades, grafos de conhecimento, ontologias e modelos de linguagem, e traduz essa pesquisa em software que a indústria pode usar diretamente.",
