  "pdf.subtitle": "Asisten prospektivitas - Australia Barat",
  "pdf.overview": "Ringkasan sesi", "pdf.covSummary": "Ringkasan", "pdf.covMapCap": "Semua titik dan wilayah yang dinilai", "pdf.covCounts": "{p} titik dinilai · {r} wilayah", "pdf.covList": "Lokasi yang dinilai", "pdf.conversation": "Percakapan", "pdf.pointDetails": "Detail titik",
  "pdf.nearestSite": "LOKASI DIKETAHUI TERDEKAT", "pdf.openOnMap": "Buka di peta",
  "pdf.waReference": "REFERENSI WA", "pdf.details": "Detail hlm. {n}",
  "pdf.latlon": "lat {lat}, lon {lon}",
  "pdf.team": "Tim", "pdf.teamTitle": "Tim di balik platform ini",
  "pdf.teamIntro": "MineTrace dan riset di sekitarnya berasal dari Tema 4 - Mempercepat Intelijen Geo-data pada ARC Training Centre in Critical Resources for the Future (CCRF), dengan dukungan UWA Centre for Natural and Technical Language Processing (NTLP). Dipimpin oleh Associate Professor Wei Liu, Tema 4 mengambil pendekatan sains geo-data terkoordinasi di seluruh Centre untuk penemuan, karakterisasi, dan pengolahan mineral kritis berbasis bukti.",
  "pdf.teamMore": "Selengkapnya tentang tim",
  "pdf.tr.wei": "Pemimpin Tema", "pdf.tb.wei": "Memimpin NTLP - Centre for Natural and Technical Language Processing - dan Tema 4 di pusat pelatihan, menetapkan arah yang menghubungkan graf pengetahuan, AI generatif, dan LLM multimodal dengan eksplorasi mineral.",
  "pdf.tr.pascal": "Fondasi platform", "pdf.tb.pascal": "Meletakkan fondasi platform tempat MineTrace berjalan - dibangun untuk menopang model dan riset yang akan datang.",
  "pdf.tr.yihao": "Riset inti - MineTrace", "pdf.tb.yihao": "Riset inti MineTrace: pemahaman dokumen multimodal, temu kembali informasi, dan tanya jawab atas arsip eksplorasi.",
  "pdf.tr.yiran": "Riset inti - MineTrace", "pdf.tb.yiran": "Riset inti MineTrace: graf pengetahuan sepanjang rantai nilai mineral kritis, mengubah bahan arsip menjadi pengetahuan yang dapat dikueri.",
  "pdf.tr.jinwen": "Bukti konsep awal", "pdf.tb.jinwen": "Membangun bukti konsep awal yang menetapkan pendekatan ini, yang kemudian berkembang menjadi platform ini.",
  "pdf.tr.daniel": "Di kedua jalur", "pdf.tb.daniel": "Bekerja di jalur riset dan platform dengan model fondasi multimodal, serta memperluas pendekatan ini ke lebih banyak kasus penggunaan eksplorasi.",
  "pdf.tr.chris": "Visualisasi data & penasihat geologi", "pdf.tb.chris": "Memberi arahan pada visualisasi data dan menghadirkan sudut pandang seorang geolog pada platform - memastikan penyajian dan pembacaan hasil berpijak pada praktik geologi.",
  "about.eyebrow": "Tentang", "about.whoTitle": "Siapa yang membangunnya",
  "about.mtLabel": "Risetnya",
  "about.mtBody": "MineTrace adalah model prospektivitas mineral di balik setiap skor di platform ini. Ia membaca arsip eksplorasi publik - geokimia GSWA, geofisika, dan struktur terpetakan - lalu mengubahnya menjadi skor yang tetap dapat dilacak ke bukti asalnya.",
  "about.seriesLabel": "Berikutnya",
  "about.seriesTitle": "Platform yang dibangun untuk lebih dari satu model",
  "about.seriesBody": "Platform ini tidak melakukan penilaian sendiri: ia memanggil layanan riset melalui HTTP dan menampilkan hasilnya. MineTrace adalah model pertama di jalur itu - jalur yang dibangun untuk membawa riset berikutnya, agar setiap hasil baru sampai ke orang yang benar-benar melakukan eksplorasi, bukan berhenti di sebuah makalah.",
  "about.ccrfEyebrow": "Bagian dari ARC Training Centre",
  "about.ccrfTheme": "Tema 4 - Mempercepat Intelijen Geo-data",
  "about.af.wei": "NTLP, UWA - Pemimpin Tema 4, CCRF",
  "about.af.jinwen": "Mahasiswa S1, Ilmu Komputer & Rekayasa Perangkat Lunak, UWA",
  "about.af.yihao": "Peneliti Pascadoktoral, CCRF",
  "about.af.yiran": "Kandidat PhD, CCRF",
  "about.af.pascal": "NTLP, UWA",
  "about.af.daniel": "Kandidat PhD, UWA - berkolaborasi dengan CCRF",
  "about.af.chris": "Research Fellow, CCRF & CET, UWA",
  // ── research hub ──
  "research.eyebrow": "Riset", "research.title": "Riset",
  "research.intro": "Riset kami menghubungkan data, bukti, dan penalaran: prospektivitas mineral, kecerdasan dokumen, dan akses basis data dengan bahasa alami. GeoPlatform menyediakan lingkungan geosains untuk mengeksplorasi metode ini.",
  "research.ladder": "Yang tumbuh darinya",
  "research.st.retrieval.t": "Pencarian", "research.st.retrieval.b": "Menemukan rekaman, halaman, atau nilainya. Misalnya: text-to-SQL atas data terstruktur, pembacaan berbasis pencarian atas dokumen.",
  "research.st.reasoning.t": "Penalaran", "research.st.reasoning.b": "Menggabungkan bukti menjadi penilaian yang tetap dapat ditelusuri. Misalnya: prospektivitas mineral dengan MineTrace.",
  "research.st.reflection.t": "Refleksi", "research.st.reflection.b": "Membiarkan sistem meninjau kembali apa yang telah dibaca dan dinilainya, lalu memunculkan pengetahuan yang tak seorang pun masukkan secara manual. Misalnya: hipotesis eksplorasi yang ditarik dari pola di ribuan laporan.",
  "research.group.application": "Aplikasi", "research.group.foundation": "Fondasi",
  "research.open": "Baca selengkapnya", "research.back": "Semua riset",
  "research.minetrace.blurb": "Sistem prospektivitas mineral berbasis web dengan Indeks Prospektivitas Komposit (CPI) yang dapat ditelusuri, bukti pendukung, dan penjelasan berbantuan LLM.",
  "research.di.blurb": "Menjelajahi koleksi dokumen dalam skala besar - arsip eksplorasi, literatur ilmiah, dan publikasi Survei Geologi - sebagai pengetahuan terstruktur yang dapat dicari, dengan setiap fakta tertaut ke halamannya.",
  "research.text2sql.blurb": "Membuat kueri bahasa sehari-hari dapat diukur pada basis data privat - Acuity mengubah skema apa pun menjadi tolok ukur bebas anotasi, lalu memakainya untuk memperbaiki dan menerapkan pencarian.",
  "pdf.teamAck": "Ucapan terima kasih",
  "pdf.teamAckBody": "Riset yang mendasarinya, MineTrace, didukung oleh ARC Training Centre in Critical Resources for the Future, di bawah Tema 4 - Mempercepat Intelijen Geo-data.",
  "pdf.teamGroup": "NTLP, UWA",
  "pdf.teamGroupBody": "Centre for Natural and Technical Language Processing (NTLP) UWA meneliti pengenalan entitas, graf pengetahuan, ontologi, dan model bahasa - serta menerjemahkan riset itu menjadi perangkat lunak yang langsung dapat dipakai industri.",
